import { test, expect } from '@playwright/test';

test.describe('Form Validation - Required Fields', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should disable submit button until all required fields are filled', async ({ page }) => {
    // Intercept the API call to get form validation rules
    await page.route('**/api/validation-rules', (route) => {
      route.continue();
    });

    // Fill in the first required field
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('John Doe');

    // Verify submit button is disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Fill in the second required field
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john.doe@example.com');

    // Verify submit button is still disabled
    await expect(submitButton).toBeDisabled();

    // Fill in the third required field
    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('123-456-7890');

    // Verify submit button is now enabled
    await expect(submitButton).not.toBeDisabled();

    // Click the submit button
    await submitButton.click();

    // Verify form is submitted successfully
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should display validation error messages when required fields are empty', async ({ page }) => {
    // Intercept the API call to get form validation rules
    await page.route('**/api/validation-rules', (route) => {
      route.continue();
    });

    // Fill in only the first required field
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('Jane Doe');

    // Verify submit button is disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Verify error message is displayed for the missing email field
    const emailError = page.getByText('Email is required');
    await expect(emailError).toBeVisible();

    // Verify error message is displayed for the missing phone number field
    const phoneError = page.getByText('Phone Number is required');
    await expect(phoneError).toBeVisible();

    // Fill in the email field
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('jane.doe@example.com');

    // Verify submit button is still disabled
    await expect(submitButton).toBeDisabled();

    // Fill in the phone number field
    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('555-123-4567');

    // Verify submit button is now enabled
    await expect(submitButton).not.toBeDisabled();

    // Click the submit button
    await submitButton.click();

    // Verify form is submitted successfully
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });
});
